<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\Accessor\ThemeVersionLocaleAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the ThemeVersionLocaleAccessor trait.
 *
 * Covers null default, string/VO assignment via withLocale,
 * getLocale/locale accessors, and isLocaleChanged with/without original.
 */
class ThemeVersionLocaleAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withLocale creates a new instance with the Locale set
     * from a string value, and getLocale returns the primitive string.
     */
    public function testWithLocaleFromString(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionLocaleAccessorUnitTest();

        // Act
        $result = $holder->withLocale('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getLocale());
    }
    /**
     * Asserts that withlocale has access to the value object
     * from a string value, and getLocale returns the primitive string.
     */
    public function testWithLocaleFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionLocaleAccessorUnitTest();

        // Act
        $result = $holder->withLocale('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->locale()->value());
    }
    public function testChangedLocale(): void
    {
        // Arrange
        $holder = new ImplWithThemeVersionLocaleAccessorUnitTest();
        $original = $holder->withLocale('one');
        $same = $holder->withLocale('one');
        $modified = $holder->withLocale('other');

        // Act
        $unchanged = $holder->isLocaleChanged();
        $withSame = $original->isLocaleChanged($same);
        $withDiferent = $original->isLocaleChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithThemeVersionLocaleAccessorUnitTest
{
    use ThemeVersionLocaleAccessor;
}
